result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/intervals.test.mjs", "content": "import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import fc from 'fast-check';
import { mergeIntervals } from './intervals.mjs';

// Arbitrary interval: [start, end] with start <= end, small integer range
const arbInterval = fc
  .tuple(fc.integer({ min: -50, max: 50 }), fc.integer({ min: -50, max: 50 }))
  .map(([a, b]) => (a <= b ? [a, b] : [b, a]));

const arbIntervals = fc.array(arbInterval, { maxLength: 20 });

// Brute-force oracle: set of integer points covered by an interval list
function coveredPoints(intervals) {
  const pts = new Set();
  for (const [s, e] of intervals) {
    for (let p = s; p <= e; p++) pts.add(p);
  }
  return pts;
}

describe('mergeIntervals properties', () => {
  // Property 1: output is sorted and strictly non-overlapping AND non-touching
  test('output is sorted with gaps > 0 between consecutive intervals', () => {
    const prop = fc.property(arbIntervals, (intervals) => {
      const out = mergeIntervals(intervals);
      for (let i = 0; i < out.length; i++) {
        const [s, e] = out[i];
        assert.ok(s <= e, `interval ${i} malformed: [${s},${e}]`);
        if (i > 0) {
          const prevEnd = out[i - 1][1];
          assert.ok(
            out[i - 1][0] < s,
            `output not sorted at index ${i}: prev start ${out[i - 1][0]} >= ${s}`
          );
          assert.ok(
            s - prevEnd > 0,
            `touching/overlapping intervals in output: [...,${prevEnd}] vs [${s},...]`
          );
        }
      }
    });
    fc.assert(prop, { numRuns: 500 });
  });

  // Property 2: point-set membership preserved (brute-force integer oracle)
  test('covered integer points are exactly preserved', () => {
    const prop = fc.property(arbIntervals, (intervals) => {
      const before = coveredPoints(intervals);
      const after = coveredPoints(mergeIntervals(intervals));
      assert.deepEqual(after, before);
    });
    fc.assert(prop, { numRuns: 500 });
  });

  // Property 3: output covers exactly the union (same as property 2 but phrased
  // as mutual containment of every input/output point)
  test('output covers exactly the union of inputs', () => {
    const prop = fc.property(arbIntervals, (intervals) => {
      const out = mergeIntervals(intervals);
      for (const [s, e] of intervals) {
        for (let p = s; p <= e; p++) {
          assert.ok(
            out.some(([os, oe]) => os <= p && p <= oe),
            `point ${p} from input [${s},${e}] not covered by output`
          );
        }
      }
      for (const [s, e] of out) {
        for (let p = s; p <= e; p++) {
          assert.ok(
            intervals.some(([is, ie]) => is <= p && p <= ie),
            `output point ${p} in [${s},${e}] not covered by any input`
          );
        }
      }
    });
    fc.assert(prop, { numRuns: 500 });
  });

  // Regression: touching intervals must merge (found by fast-check)
  test('regression: touching intervals [1,2] and [2,3] merge to [1,3]', () => {
    assert.deepEqual(mergeIntervals([[1, 2], [2, 3]]), [[1, 3]]);
  });
});
"})
